import{_ as a,o as i,c as r,a2 as l}from"./chunks/framework.DSQXGnvq.js";const d=JSON.parse('{"title":"概览","description":"","frontmatter":{},"headers":[],"relativePath":"overview.md","filePath":"overview.md"}'),p={name:"overview.md"};function t(c,e,o,h,n,s){return i(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="概览" tabindex="-1">概览 <a class="header-anchor" href="#概览" aria-label="Permalink to &quot;概览&quot;">​</a></h1><h2 id="什么是-pyspice" tabindex="-1">什么是 PySpice？ <a class="header-anchor" href="#什么是-pyspice" aria-label="Permalink to &quot;什么是 PySpice？&quot;">​</a></h2><p>PySpice 是一个开源 Python 模块，为 <a href="http://ngspice.sourceforge.net" target="_blank" rel="noreferrer">Ngspice</a> 和 <a href="https://xyce.sandia.gov" target="_blank" rel="noreferrer">Xyce</a> 电路模拟器提供 Python 接口。</p><p><a href="http://ngspice.sourceforge.net" target="_blank" rel="noreferrer">Ngspice</a> 源自著名的 <a href="https://en.wikipedia.org/wiki/SPICE" target="_blank" rel="noreferrer">SPICE</a> 电路模拟器，<a href="https://xyce.sandia.gov" target="_blank" rel="noreferrer">Xyce</a> 则是由 <a href="http://www.sandia.gov" target="_blank" rel="noreferrer">Sandia 国家实验室</a> 开发的 SPICE 兼容模拟器。</p><p>PySpice 允许你：</p><ul><li>通过网表定义电路</li><li>使用 Ngspice 和 Xyce 进行仿真</li><li>使用 NumPy 和 Matplotlib 分析仿真结果</li></ul><h2 id="许可协议" tabindex="-1">许可协议 <a class="header-anchor" href="#许可协议" aria-label="Permalink to &quot;许可协议&quot;">​</a></h2><p>PySpice 基于 <a href="https://www.gnu.org/licenses/quick-guide-gplv3.en.html" target="_blank" rel="noreferrer">GPLv3</a> 许可协议发布。</p><h2 id="演讲与论文" tabindex="-1">演讲与论文 <a class="header-anchor" href="#演讲与论文" aria-label="Permalink to &quot;演讲与论文&quot;">​</a></h2><p>你可以观看在 <a href="http://pyparis.org/" target="_blank" rel="noreferrer">PyParis 2017</a> 会议上发表的演讲 <a href="https://www.slideshare.net/PoleSystematicParisRegion/pyparis2017-circuit-simulation-using-python-by-fabrice-salvaire" target="_blank" rel="noreferrer">Circuit Simulation using Python</a>（<a href="https://pyspice.fabrice-salvaire.fr/pyparis-2017-talk.pdf" target="_blank" rel="noreferrer">PDF 文件</a>）。</p><h2 id="深入学习-pyspice" tabindex="-1">深入学习 PySpice <a class="header-anchor" href="#深入学习-pyspice" aria-label="Permalink to &quot;深入学习 PySpice&quot;">​</a></h2><p>了解 PySpice 功能的最佳方式是查看示例：</p><ul><li><a href="/pyspice/example-introduction.html">示例</a></li><li>API 参考</li><li>参考文献</li></ul><h2 id="pyspice-如何用于学习" tabindex="-1">PySpice 如何用于学习？ <a class="header-anchor" href="#pyspice-如何用于学习" aria-label="Permalink to &quot;PySpice 如何用于学习？&quot;">​</a></h2><p>PySpice 提供了大量涵盖多个主题的示例。</p><h2 id="支持的平台" tabindex="-1">支持的平台 <a class="header-anchor" href="#支持的平台" aria-label="Permalink to &quot;支持的平台&quot;">​</a></h2><p>PySpice 可在 Linux、64 位 Windows 和 macOS 上运行。</p><h2 id="如何安装" tabindex="-1">如何安装？ <a class="header-anchor" href="#如何安装" aria-label="Permalink to &quot;如何安装？&quot;">​</a></h2><p>安装步骤见<a href="/pyspice/installation.html">安装指南</a>。</p><h2 id="pyspice-与-ltspice-等模拟器的区别" tabindex="-1">PySpice 与 LTspice 等模拟器的区别？ <a class="header-anchor" href="#pyspice-与-ltspice-等模拟器的区别" aria-label="Permalink to &quot;PySpice 与 LTspice 等模拟器的区别？&quot;">​</a></h2><ul><li>PySpice、Ngspice 和 Xyce 都是<a href="https://en.wikipedia.org/wiki/Free_software" target="_blank" rel="noreferrer">自由软件</a>，开源</li><li>PySpice 没有原理图编辑器或 GUI，但</li><li>它拥有 Python 强大的数据分析能力</li><li>提供现代数据分析工具</li><li>开放的架构使功能不受限制</li></ul><p>（不过你可以从 KiCad 导出网表到 PySpice。）</p><h2 id="无-gui-模拟器的优势" tabindex="-1">无 GUI 模拟器的优势？ <a class="header-anchor" href="#无-gui-模拟器的优势" aria-label="Permalink to &quot;无 GUI 模拟器的优势？&quot;">​</a></h2><p>编写网表并非总是轻松，原理图编辑器有助于电路的可视化。Circuit_macros 和 Tikz 等工具确实需要学习，但学习曲线不会比学乐器更陡。</p><p>每个工具都有各自的优缺点，往往互为补充。</p><p>主要优势：</p><ul><li>用代码完整描述仿真项目，无需鼠标操作 GUI</li><li>可用 Git 轻松进行版本管理</li><li>在编辑器和终端间快速修改并重新运行仿真，比如注释掉一个二极管看效果。而用 GUI 则需要多次操作</li><li>借助 Pyterate 工具，可以用文本、公式和图表丰富仿真内容</li></ul><p>能否同时使用两种方式？技术上的答案是肯定的。例如 Modelica 语言使用注释概念来描述原理图。KiCad 等原理图编辑器也可以升级后与 PySpice 紧密集成。</p><h2 id="pyspice-相比-ngspice-xyce-的优势" tabindex="-1">PySpice 相比 Ngspice/Xyce 的优势？ <a class="header-anchor" href="#pyspice-相比-ngspice-xyce-的优势" aria-label="Permalink to &quot;PySpice 相比 Ngspice/Xyce 的优势？&quot;">​</a></h2><ul><li><p>你可以用 Python 控制网表和仿真</p><p>这超越了 SPICE 的<em>参数</em>和<em>表达式</em>，使蒙特卡洛仿真等变得更容易</p></li><li><p>你可以用 Python 科学计算包分析输出</p><p>这超越了 TclSpice 等工具</p></li></ul><h2 id="pyspice-如何与-ngspice-交互" tabindex="-1">PySpice 如何与 Ngspice 交互？ <a class="header-anchor" href="#pyspice-如何与-ngspice-交互" aria-label="Permalink to &quot;PySpice 如何与 Ngspice 交互？&quot;">​</a></h2><ul><li><p>PySpice 可以解析 SPICE 网表并生成等效 Python 代码，或直接实例化</p></li><li><p>PySpice 可以生成 SPICE 网表</p></li><li><p>PySpice 可以将仿真发送到 Ngspice，并通过<em>服务器</em>或<em>共享</em>模式读取输出</p><p>默认使用服务器模式。共享模式仅用于需要高级功能的场景</p></li></ul><p>使用<em>共享</em>模式时：</p><ul><li>PySpice 允许在 Python（甚至 C 语言）中定义外部电压和电流源</li><li>PySpice 允许在仿真过程中向模拟器发送和接收数据</li><li>使用 CFFI 实现 C 到 Python 的接口</li></ul><h2 id="pyspice-如何与-xyce-交互" tabindex="-1">PySpice 如何与 Xyce 交互？ <a class="header-anchor" href="#pyspice-如何与-xyce-交互" aria-label="Permalink to &quot;PySpice 如何与 Xyce 交互？&quot;">​</a></h2><p>目前，PySpice 将 Xyce 作为子进程运行并读取原始输出。</p><h2 id="如何定义网表" tabindex="-1">如何定义网表？ <a class="header-anchor" href="#如何定义网表" aria-label="Permalink to &quot;如何定义网表？&quot;">​</a></h2><ul><li>使用面向对象 API 定义网表</li><li>PySpice 也可以处理 SPICE 网表，并从 KiCad 等原理图编辑器导入网表</li></ul><h2 id="能否使用解释器命令运行-ngspice" tabindex="-1">能否使用解释器命令运行 Ngspice？ <a class="header-anchor" href="#能否使用解释器命令运行-ngspice" aria-label="Permalink to &quot;能否使用解释器命令运行 Ngspice？&quot;">​</a></h2><p>通过 Ngspice 共享库绑定，你不必局限于 PySpice 的面向对象 API。你可以像以前一样运行 Ngspice，只需将仿真输出转换为 NumPy 数组。示例请参考 Ngspice 共享模式示例。</p><h2 id="如何处理-spice-库" tabindex="-1">如何处理 SPICE 库？ <a class="header-anchor" href="#如何处理-spice-库" aria-label="Permalink to &quot;如何处理 SPICE 库？&quot;">​</a></h2><ul><li>PySpice 提供一个库管理器，可扫描路径中的库文件</li><li>可以使用 <em>include</em> 指令原样包含库</li><li>子电路可以定义为 Python 类</li></ul><h2 id="如何处理单位" tabindex="-1">如何处理单位？ <a class="header-anchor" href="#如何处理单位" aria-label="Permalink to &quot;如何处理单位？&quot;">​</a></h2><ul><li>PySpice 提供一个支持国际单位制的单位模块</li><li>可以使用函数快捷方式或特殊语法定义带单位的值，例如 <code>kilo(1.2)</code>、<code>1.2@u_kV</code>、<code>1.2@u_mΩ</code></li></ul><h2 id="要求-python-版本" tabindex="-1">要求 Python 版本？ <a class="header-anchor" href="#要求-python-版本" aria-label="Permalink to &quot;要求 Python 版本？&quot;">​</a></h2><p>PySpice 需要 Python 3，推荐 3.5 以上版本以使用新的 <code>@</code> 语法处理单位。</p><h2 id="要求-ngspice-版本" tabindex="-1">要求 Ngspice 版本？ <a class="header-anchor" href="#要求-ngspice-版本" aria-label="Permalink to &quot;要求 Ngspice 版本？&quot;">​</a></h2><p>应使用最新版 Ngspice，并确保按照 Ngspice 手册编译 -- 检查是否有人启用了可能破坏 PySpice 的实验性功能。</p><p><em>注意：Ngspice 不随 PySpice 分发！</em></p><h2 id="要求-xyce-版本" tabindex="-1">要求 Xyce 版本？ <a class="header-anchor" href="#要求-xyce-版本" aria-label="Permalink to &quot;要求 Xyce 版本？&quot;">​</a></h2><p>应使用 Sandia 提供的最新版本。</p><h2 id="支持哪些-spice-变体" tabindex="-1">支持哪些 SPICE 变体？ <a class="header-anchor" href="#支持哪些-spice-变体" aria-label="Permalink to &quot;支持哪些 SPICE 变体？&quot;">​</a></h2><p>目前 PySpice 仅支持 Ngspice 和 Xyce。</p><p>但 PySpice 可以轻松支持任何提供类似 Ngspice API 的仿真器。</p><h2 id="还需要注意什么" tabindex="-1">还需要注意什么？ <a class="header-anchor" href="#还需要注意什么" aria-label="Permalink to &quot;还需要注意什么？&quot;">​</a></h2><p>用户应注意以下免责声明：</p><ul><li>Ngspice 和 PySpice 不提供任何担保。在实际设计中务必谨慎使用</li><li>最好使用工业级仿真器交叉验证仿真结果</li><li>Ngspice 不符合工业质量保证流程</li><li>仿真是设计工具，不是现实世界的完美描述</li></ul>',57)])])}const y=a(p,[["render",t]]);export{d as __pageData,y as default};
